use sdocx::*;
fn main() {
 let args:Vec<String>=std::env::args().collect(); let case=&args[1]; let out=std::path::Path::new(&args[2]); std::fs::create_dir_all(out).unwrap();
 let (coords,pressures,argb)=match case.as_str(){
 "phase2" => (vec![[22.125,25.375],[31.125,36.375],[43.125,26.375],[53.125,39.375]],vec![1.0,0.0,0.65,0.25],0x8033cc55u32), "phase4" => (vec![[18.375,19.125],[25.375,28.125],[34.375,20.125],[43.375,29.125]],vec![0.02,0.95,0.15,0.8],0x8033cc55u32), "boundary" => (vec![[21.75,30.25],[39.75,43.25],[54.75,27.25],[67.75,40.25]],vec![0.9,0.1,0.7,0.3],0x8033cc55u32), "short" => (vec![[25.25,28.5],[32.25,39.5],[42.25,30.5],[49.25,41.5],[55.25,31.5]],vec![0.1,0.9,0.3,0.8,0.2],0x8033cc55u32),
 "crossing" => (vec![[35.5,35.75],[86.0,85.5],[35.5,85.5],[86.0,35.75]],vec![0.2,0.9,0.4,1.0],0x8033cc55u32), _=>panic!()};
 let size=if case=="boundary" {9.0001} else {8.5}; let width=if case=="phase4" {64} else {128}; let selected=match case.as_str() {"phase2"=>Marker3OutputScale::Two,"phase4"=>Marker3OutputScale::Four,_=>Marker3OutputScale::One};
 let rendering:StrokeRendering=serde_json::from_value(serde_json::json!({"metadata":null,"pen_name":"com.samsung.android.sdk.pen.pen.preload.Marker3","advanced_settings":"5;","tool_type_raw":1,"properties":{"compressed":true,"replay_only":false,"stylus_channels":false,"eraser":false,"fixed_width":false,"millisecond_timestamps":false,"top_layer_pen":true,"alpha_lock":false,"binary_added":true,"generated":false,"fixed_opacity":false,"rainbow_effect":false,"straighten":false,"reveal_mode":false},"style":{"color_argb":argb,"pen_size":size,"stroke_type_raw":0,"trailing_data":[]}})).unwrap();
 let stroke=Stroke {rendering:Some(rendering),bbox:BoundingBox::default(),points:coords.iter().map(|p|Point{x:p[0],y:p[1]}).collect(),pressures,timestamps:(0..coords.len()).map(|i| (8*i) as i64).collect(),tilts:vec![0.0;coords.len()],orientations:vec![0.0;coords.len()],color:Some(Color {r:(argb>>16) as u8,g:(argb>>8) as u8,b:argb as u8}),pen_width:size};
 let doc=Document {pages:vec![Page {uuid:"control".into(),width,height:width,content_bbox:BoundingBox::default(),background_color:None,template:None,background:Default::default(),objects:vec![stroke.into()]}],metadata:Default::default()};
 for (name,scale) in [("baseline",None),("profile",Some(selected))] {let mut options=RenderOptions::default(); options.marker3_output_scale=scale; std::fs::write(out.join(format!("{name}.svg")),&render_document_svg(&doc,&options)[0].svg).unwrap();std::fs::write(out.join(format!("{name}.pdf")),render_document_pdf(&doc,&options,&Default::default()).unwrap()).unwrap();}
}
